7	/**
8	 * Assigns a new owner's {@code customerCode} before it is saved: the 4-digit sequence is
9	 * one more than the number of owners already in the same city, so codes run consecutively
10	 * within each city.
11	 */
12	public class AssignOwnerCustomerCode {
13	
14	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
15	        long inCity = ownerRepository.findAll().stream()
16	            .filter(existing -> existing.getCity() != null && existing.getCity().equals(owner.getCity()))
17	            .count();
18	        int sequence = (int) inCity + 1;
19	        owner.setCustomerCode(OwnerCustomerCodes.format(owner.getCity(), owner.getLastName(), sequence));
20	    }
21	}
