10	/**
11	 * Rejects a create-owner request that is missing or blank in any required field
12	 * (firstName, lastName, address, city, telephone) before {@link BuildOwner} runs. Reads the
13	 * body published by {@link NormalizeOwnerAddress}, so the address is checked in its
14	 * normalized form — an address that is blank once normalized is rejected.
15	 */
16	public class RequireOwnerFields {
17	
18	    public void service(@Val OwnerFieldsDto request) throws MissingOwnerFieldsException {
19	        List<String> missing = new ArrayList<>();
20	        if (isBlank(request.getFirstName())) {
21	            missing.add("firstName");
22	        }
23	        if (isBlank(request.getLastName())) {
24	            missing.add("lastName");
25	        }
26	        if (isBlank(request.getAddress())) {
27	            missing.add("address");
28	        }
29	        if (isBlank(request.getCity())) {
30	            missing.add("city");
31	        }
32	        if (isBlank(request.getTelephone())) {
33	            missing.add("telephone");
34	        }
35	        if (!missing.isEmpty()) {
36	            throw new MissingOwnerFieldsException(missing);
37	        }
38	    }
39	
40	    private static boolean isBlank(String value) {
41	        return value == null || value.isBlank();
42	    }
43	}
