4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Records how many existing owners already shared this owner's name at creation time:
9	 * the count of owners with the same firstName and lastName (compared case-insensitively).
10	 * Computed before the new owner is saved, so it never counts itself.
11	 */
12	public class AssignOwnerNamesakeCount {
13	
14	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
15	        int count = 0;
16	        for (Owner existing : ownerRepository.findAll()) {
17	            if (sameName(existing.getFirstName(), owner.getFirstName())
18	                    && sameName(existing.getLastName(), owner.getLastName())) {
19	                count++;
20	            }
21	        }
22	        owner.setNamesakeCount(count);
23	    }
24	
25	    private static boolean sameName(String a, String b) {
26	        return a == null ? b == null : a.equalsIgnoreCase(b);
27	    }
28	}
